package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string = ""
var WsBalEd string = ""
var WsTotEd string = ""

var ledgerLines []string
var ledgerIdx int
var currentRec LedgerRec

func InputDone() bool { return WsEofFlag == "Y" }
func FirstRecord() bool { return WsFirstFlag == "Y" }

func storeDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// truncate toward zero to scale
	v = v.Truncate(int32(scale))
	scaled := v.Shift(int32(scale)) // v * 10^scale, may be negative
	mod := decimal.New(1, int32(intDigits+scale)) // 10^(intDigits+scale)
	// if |scaled| >= mod, keep low-order digits: scaled % mod (trunc toward zero)
	absScaled := scaled.Abs()
	if absScaled.GreaterThanOrEqual(mod) {
		q := scaled.Div(mod).Truncate(0)
		r := scaled.Sub(q.Mul(mod))
		v = r.Shift(int32(-scale))
	} else {
		v = scaled.Shift(int32(-scale))
	}
	return v
}

func storeInt64(v int64, intDigits int) int64 {
	mod := int64(1)
	for i := 0; i < intDigits; i++ {
		mod *= 10
	}
	if v >= mod || v <= -mod {
		// keep low-order digits preserving sign
		if v < 0 {
			av := -v
			av = av % mod
			v = -av
		} else {
			v = v % mod
		}
	}
	return v
}

// formatting helpers

func formatEdited(abs decimal.Decimal, intDigits int, pic string) string {
	// abs is non-negative, already truncated to 2 decimals, and overflow (mod) applied
	// pic is used only to determine comma positions; we use generic parser
	// Build picture runes
	picRunes := []rune(pic)
	// count digit placeholders
	nDigits := 0
	for _, c := range picRunes {
		if c == 'Z' || c == '9' {
			nDigits++
		}
	}
	// digits of integer part
	// abs has scale 2, but we will compute scaled integer to extract fraction
	scaled := abs.Shift(2).Truncate(0) // integer scaled
	// fraction = scaled % 100
	mod100 := decimal.NewFromInt(100)
	q100 := scaled.Div(mod100).Truncate(0)
	fracDec := scaled.Sub(q100.Mul(mod100)) // 0..99
	fracInt := fracDec.IntPart() // 0..99, abs so non-negative
	intPartDec := q100.Abs() // integer part
	intPartInt := intPartDec.IntPart() // fits in int64
	// handle overflow for edited: high-order digits dropped
	// pow10 = 10^intDigits
	pow10 := int64(1)
	for i := 0; i < intDigits; i++ {
		pow10 *= 10
	}
	if intPartInt >= pow10 {
		intPartInt = intPartInt % pow10
	}
	// build digits array zero-padded to intDigits
	digits := make([]int, intDigits)
	tmp := intPartInt
	for i := intDigits - 1; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	// isZ per digit placeholder in order
	isZ := make([]bool, intDigits)
	di := 0
	for _, c := range picRunes {
		if c == 'Z' || c == '9' {
			isZ[di] = (c == 'Z')
			di++
		}
	}
	// find first non-zero index
	firstNonZero := -1
	for i := 0; i < intDigits; i++ {
		if digits[i] != 0 {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		// all zeros -> the last digit (which is 9) is the first non-zero (0)
		firstNonZero = intDigits - 1
	}
	suppressed := make([]bool, intDigits)
	for i := 0; i < intDigits; i++ {
		if i < firstNonZero && isZ[i] {
			suppressed[i] = true
		} else {
			suppressed[i] = false
		}
	}
	// build result for integer part + commas
	// We iterate over picRunes that are before the '.' (or whole pic if no dot handling separate)
	// For our pics, there is a '.' then "99" for fraction. We'll handle integer pic part separately.
	// Split pic at '.'
	dotIdx := -1
	for i, c := range picRunes {
		if c == '.' {
			dotIdx = i
			break
		}
	}
	var intPicRunes []rune
	if dotIdx >= 0 {
		intPicRunes = picRunes[:dotIdx]
	} else {
		intPicRunes = picRunes
	}
	// Map placeholders to digits
	resInt := make([]rune, len(intPicRunes))
	placeholderIdx := 0
	for i, c := range intPicRunes {
		if c == 'Z' || c == '9' {
			if suppressed[placeholderIdx] {
				resInt[i] = ' '
			} else {
				resInt[i] = rune('0' + digits[placeholderIdx])
			}
			placeholderIdx++
		} else if c == ',' {
			// count placeholders before this comma
			// number of placeholders before position i
			cntBefore := 0
			for k := 0; k < i; k++ {
				if intPicRunes[k] == 'Z' || intPicRunes[k] == '9' {
					cntBefore++
				}
			}
			allSuppressedBefore := true
			for p := 0; p < cntBefore; p++ {
				if !suppressed[p] {
					allSuppressedBefore = false
					break
				}
			}
			if allSuppressedBefore {
				resInt[i] = ' '
			} else {
				resInt[i] = ','
			}
		} else {
			resInt[i] = c
		}
	}
	intStr := string(resInt)
	fracStr := fmt.Sprintf("%02d", fracInt)
	return intStr + "." + fracStr
}

func formatAmtEd(v decimal.Decimal) string {
	// PIC ZZ,ZZ9.99 unsigned, 5 int digits
	// Drop high-order if needed via modulus (handled inside formatEdited)
	return formatEdited(v.Abs(), 5, "ZZ,ZZ9.99")
}

func formatBalEd(v decimal.Decimal) string {
	sign := ' '
	if v.Sign() < 0 {
		sign = '-'
	}
	abs := v.Abs()
	intPart := formatEdited(abs, 7, "Z,ZZZ,ZZ9.99")
	return string(sign) + intPart
}

func formatTotEd(v decimal.Decimal) string {
	sign := ' '
	if v.Sign() < 0 {
		sign = '-'
	}
	abs := v.Abs()
	intPart := formatEdited(abs, 9, "ZZZ,ZZZ,ZZ9.99")
	return string(sign) + intPart
}

func padRight(s string, n int) string {
	if len(s) >= n {
		if len(s) > n {
			return s[:n]
		}
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseAmt(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// s contains digits only
	d, err := decimal.NewFromString(s)
	if err != nil {
		// if contains spaces, treat as 0
		return decimal.NewFromInt(0)
	}
	return d.Shift(-2)
}

func MAIN_PARA() {
	fdata, err := os.ReadFile("input.dat")
	if err != nil {
		if !os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		fdata = []byte{}
	}
	content := string(fdata)
	// split lines
	rawLines := strings.Split(content, "\n")
	// If file ends with newline, Split gives extra empty at end; we need to handle COBOL line sequential:
	// Each line is a record, including last empty line if file ends with newline? In COBOL LINE SEQUENTIAL, trailing newline not a record.
	// Remove last element if content ends with "\n" and last is ""? Actually we want to ignore final empty after trailing newline.
	// But we must keep empty lines in middle as records.
	// Process: if content == "" then no lines
	if content == "" {
		ledgerLines = []string{}
	} else {
		// if content ends with \n, the last split entry is "", we should drop it
		if strings.HasSuffix(content, "\n") {
			rawLines = rawLines[:len(rawLines)-1]
		}
		ledgerLines = rawLines
	}
	ledgerIdx = 0
	READ_PARA()
	for !InputDone() {
		PROCESS_PARA()
	}
	if !FirstRecord() {
		ACCT_BREAK_PARA()
		BRANCH_BREAK_PARA()
	}
	// CLOSE LEDGER-FILE (no-op)
	GRAND_PARA()
}

func READ_PARA() {
	if ledgerIdx >= len(ledgerLines) {
		WsEofFlag = "Y"
		return
	}
	line := ledgerLines[ledgerIdx]
	ledgerIdx++
	// pad/truncate to 14
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	// remove possible \r at end (if file had \r\n, our split on \n leaves \r)
	if len(line) > 0 && line[len(line)-1] == '\r' {
		// This would have been inside line; but we already handled length. Handle generic:
		// Actually if original had \r\n, rawLines entries end with \r; we kept it. Our len check includes it. For correct parsing, strip \r.
		// Instead we handle at rawLines level: but easier here: if line contains \r, replace?
		// We'll treat line as is but our fields extraction should ignore \r. Simplest: if ledgerLines entry had \r, it is part of line; we should have removed it before padding.
		// Redo: We'll clean line
	}
	// clean \r
	line = strings.ReplaceAll(line, "\r", "")
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	}
	brBranch := line[0:2]
	brAcct := line[2:6]
	brType := line[6:7]
	brAmtStr := line[7:14]
	currentRec.BrBranch = brBranch
	currentRec.BrAcct = brAcct
	currentRec.BrType = brType
	currentRec.BrAmt = parseAmt(brAmtStr)
}

func PROCESS_PARA() {
	if FirstRecord() {
		WsPrevBranch = currentRec.BrBranch
		WsPrevAcct = currentRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if currentRec.BrBranch != WsPrevBranch {
			ACCT_BREAK_PARA()
			BRANCH_BREAK_PARA()
			WsPrevBranch = currentRec.BrBranch
			WsPrevAcct = currentRec.BrAcct
		} else {
			if currentRec.BrAcct != WsPrevAcct {
				ACCT_BREAK_PARA()
				WsPrevAcct = currentRec.BrAcct
			}
		}
	}
	POST_PARA()
	READ_PARA()
}

func POST_PARA() {
	WsAmtEd = formatAmtEd(currentRec.BrAmt)
	switch currentRec.BrType {
	case "D":
		WsBal = storeDecimal(WsBal.Add(currentRec.BrAmt), 7, 2)
		fmt.Println(currentRec.BrAcct + " D " + WsAmtEd)
	case "C":
		WsBal = storeDecimal(WsBal.Sub(currentRec.BrAmt), 7, 2)
		fmt.Println(currentRec.BrAcct + " C " + WsAmtEd)
	default:
		WsSkipped = storeInt64(WsSkipped+1, 2)
		fmt.Println(currentRec.BrAcct + " ? SKIPPED")
	}
}

func ACCT_BREAK_PARA() {
	WsBalEd = formatBalEd(WsBal)
	fmt.Println("  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd)
	WsBranchTot = storeDecimal(WsBranchTot.Add(WsBal), 9, 2)
	WsBal = storeDecimal(decimal.NewFromInt(0), 7, 2)
}

func BRANCH_BREAK_PARA() {
	WsTotEd = formatTotEd(WsBranchTot)
	fmt.Println(" BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd)
	WsGrandTot = storeDecimal(WsGrandTot.Add(WsBranchTot), 9, 2)
	WsBranchTot = storeDecimal(decimal.NewFromInt(0), 9, 2)
}

func GRAND_PARA() {
	WsTotEd = formatTotEd(WsGrandTot)
	fmt.Println("GRAND TOTAL:" + WsTotEd)
	// WsSkipped display as PIC 99 zero-padded width 2
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	fmt.Println("SKIPPED: " + skippedStr)
}

func main() {
	// initialize WS fields that are SPACES
	WsPrevBranch = padRight("", 2)
	WsPrevAcct = padRight("", 4)
	MAIN_PARA()
}

